begin;

-- 1) 기존 데이터 백업 (되돌리기용, 정책 미포함 순수 사본)
create table if not exists public.specs_tbr_legacy as table public.specs_tbr;

-- 2) 명칭 변경 specs_tbr -> products_spec_tbr (RLS 정책·grant·인덱스 자동 이동)
alter table public.specs_tbr rename to products_spec_tbr;

-- 2-1) 속성 유니크 제약 제거 — 이제 sku 기준이라 동일속성(신규/기존 sku) 공존 허용
alter table public.products_spec_tbr drop constraint if exists tbr_specs_brand_pattern_size_ply_rating_key;

-- 3) sku 기준 재구성: 기존 카탈로그 행 비우고 제품(TBR/LTR) 로스터 1:1 재적재
--    제원은 기존 specs_tbr 에서 sku -> description(속성) 순 매칭으로 이관(제원만, 가격 없음)
delete from public.products_spec_tbr;

